    sh_off: "Oprit",
    sh_mode: "Mod",
    sh_mode_heat: "Încălzire",
    sh_mode_cool: "Răcire",
    sh_mode_heat_cool: "Încălzire și răcire",
    sh_mode_auto: "Automat",
    sh_mode_dry: "Uscare",
    sh_mode_fan_only: "Doar ventilator",
